  #define OSCILLATORS_XOSC32M_FORCEMODE_VAL_Standby (0x1UL) /*!< Force to Standby mode                                         */
  #define OSCILLATORS_XOSC32M_FORCEMODE_VAL_Pierce (0x2UL) /*!< Force to Pierce mode                                           */
  #define OSCILLATORS_XOSC32M_FORCEMODE_VAL_ExtSqrSin192M (0x3UL) /*!< Force to External Square or External Sine 192MHz mode   */
  #define OSCILLATORS_XOSC32M_FORCEMODE_VAL_ExtSin (0x4UL) /*!< Force to External Sine mode                                    */

/* EN @Bit 31 : Enable force mode for the XOSC32M */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Pos (31UL) /*!< Position of EN field.                                               */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Msk (0x1UL << OSCILLATORS_XOSC32M_FORCEMODE_EN_Pos) /*!< Bit mask of EN field.      */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Min (0x0UL) /*!< Min enumerator value of EN field.                                  */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Max (0x1UL) /*!< Max enumerator value of EN field.                                  */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Disabled (0x0UL) /*!< Disable force mode for FSM                                    */
  #define OSCILLATORS_XOSC32M_FORCEMODE_EN_Enabled (0x1UL) /*!< Enable force mode for FSM                                      */


/* OSCILLATORS_XOSC32M_PEAKDETECTOR: Peak Detector pkdOut */
