  #define RADIO_DFT_DTB0CONFIG_EN_Msk (0x1UL << RADIO_DFT_DTB0CONFIG_EN_Pos) /*!< Bit mask of EN field.                        */
  #define RADIO_DFT_DTB0CONFIG_EN_Min (0x0UL)        /*!< Min enumerator value of EN field.                                    */
  #define RADIO_DFT_DTB0CONFIG_EN_Max (0x1UL)        /*!< Max enumerator value of EN field.                                    */
  #define RADIO_DFT_DTB0CONFIG_EN_Disabled (0x0UL)   /*!< Digital test bus is disabled                                         */
  #define RADIO_DFT_DTB0CONFIG_EN_Enabled (0x1UL)    /*!< Digital test bus is enabled                                          */


/* RADIO_DFT_DTB1CONFIG: Digital Test Bus 1 (DTB1) configuration */
  #define RADIO_DFT_DTB1CONFIG_ResetValue (0x00000000UL) /*!< Reset value of DTB1CONFIG register.                              */

/* SELMUX @Bits 0..1 : Select multiplexer for DTB1 */
  #define RADIO_DFT_DTB1CONFIG_SELMUX_Pos (0UL)      /*!< Position of SELMUX field.                                            */
  #define RADIO_DFT_DTB1CONFIG_SELMUX_Msk (0x3UL << RADIO_DFT_DTB1CONFIG_SELMUX_Pos) /*!< Bit mask of SELMUX field.            */
