  #define REGULATORS_VREGMAIN_CONFIG_FORCEMODE_VAL_Pfm (0x2UL) /*!< Force to PFM mode                                          */
  #define REGULATORS_VREGMAIN_CONFIG_FORCEMODE_VAL_Pwm (0x3UL) /*!< Force to PWM mode                                          */

