  #define RRAMC_POWER_LOWPOWERCONFIG_FORCEONRRAMC_Off (0x0UL) /*!< The RRAMC power request is inactive                         */
  #define RRAMC_POWER_LOWPOWERCONFIG_FORCEONRRAMC_On (0x1UL) /*!< The RRAMC power request is active                            */

