  #define RRAMC_POWER_LOWPOWERCONFIG_TRCREINIT_Disabled (0x0UL) /*!< TRC re-initialization is disabled during wakeup           */
  #define RRAMC_POWER_LOWPOWERCONFIG_TRCREINIT_Enabled (0x1UL) /*!< TRC re-initialization is enabled during wakeup             */

